<?php $f=$data['food']; ?>
<p class="lead">Record the food and handling details accurately. Screening records declarations and does not certify that food is safe.</p>
<?php if (!$data['organizations']): ?><p class="empty-state">First <a class="underlined" href="/organizations">create or link a donor organization</a>.</p><?php else: ?>
<article class="panel form-panel"><form data-api="/api/donations">
<?php if ($f): ?><input type="hidden" name="id" value="<?= e($f['id']) ?>"><?php endif ?>
<?php choice('organization_id','Donor organization',array_column($data['organizations'],'name','id'),$f['organization_id'] ?? '');field('name','Food name','text',$f['name'] ?? '','required maxlength="160"');field('description','Description','textarea',$f['description'] ?? '', 'required');choice('category_id','Category',array_column($data['categories'],'name','id'),$f['category_id'] ?? ''); ?>
<div class="field-pair"><?php field('quantity','Quantity','number',$f['quantity'] ?? '', 'required min="0.001" max="100000" step="0.001"');choice('unit','Unit',['kg'=>'Kilograms','g'=>'Grams','portions'=>'Portions','items'=>'Items'],$f['unit'] ?? 'kg'); ?></div>
<?php field('unit_mass_kg','Weight per portion/item (kg; ignored for kg or grams)','number',$f['unit_mass_kg'] ?? '', 'min="0.001" max="1000" step="0.001"');field('prepared_at','Prepared / packed at (local time)','datetime-local',$f['prepared_at'] ?? '', 'required');field('use_by','Use-by date and time (local time)','datetime-local',$f['use_by'] ?? '', 'required');field('deadline','Latest pickup (local time; no later than use-by)','datetime-local',$f['deadline'] ?? '', 'required'); ?>
<?php choice('storage_method','Storage method',['ambient'=>'Ambient','chilled'=>'Chilled','frozen'=>'Frozen','hot'=>'Hot holding'],$f['storage_method'] ?? 'ambient');field('temperature_c','Measured storage temperature (°C)','number',$f['temperature_c'] ?? '', 'min="-100" max="150" step="0.1"');choice('packaging','Packaging condition',['intact'=>'Intact, clean and covered','unknown'=>'Unknown — needs inspection','damaged'=>'Damaged — ineligible'],$f['packaging'] ?? 'intact');field('ingredients','Ingredients','textarea',$f['ingredients'] ?? '', 'required');field('allergens','Allergens (write “None declared” if applicable)','textarea',$f['allergens'] ?? '', 'required'); ?>
<fieldset><legend>Handling declarations</legend><?php checkfield('handling_declared','Handled hygienically and stored separately from waste',!empty($f['handling_declared']));checkfield('unserved','Food has not been served to customers',!empty($f['unserved']));checkfield('contamination_free','No known contamination, spoilage or pest damage',!empty($f['contamination_free'])); ?></fieldset>
<?php field('address','Pickup address','textarea',$f['address'] ?? '', 'required'); ?><div class="field-pair"><?php field('latitude','Latitude','number',$f['latitude'] ?? '', 'required step="any" min="-90" max="90"');field('longitude','Longitude','number',$f['longitude'] ?? '', 'required step="any" min="-180" max="180"'); ?></div><button class="quiet-button" type="button" data-location>Use my current location</button>
<?php formend($f ? 'Save and re-screen donation' : 'Create donation and screen eligibility'); ?></article><?php endif ?>
